#pragma once
#define BATTERIES_PACKED_PACKED_PTR_HPP

#include <batteries/config.hpp>
//
#include <batteries/assert.hpp>
#include <batteries/buffer.hpp>
#include <batteries/int_types.hpp>

#include <type_traits>

namespace batt {

template <typename T, typename OffsetT>
struct PackedPtr {
    using Self = PackedPtr;

    using value_type = T;
    using offset_type = OffsetT;
    using pointer = std::add_pointer_t<T>;
    using const_pointer = std::add_pointer_t<std::add_const_t<T>>;

    using reference = typename std::conditional_t<std::is_same_v<T, void>, StaticType<void>,
                                                  std::add_lvalue_reference<T>>::type;

    using const_reference = typename std::conditional_t<std::is_same_v<T, void>, StaticType<void>,
                                                        std::add_lvalue_reference<std::add_const_t<T>>>::type;

    //----- --- -- -  -  -   -

    OffsetT offset_;

    //----- --- -- -  -  -   -

    PackedPtr(const PackedPtr&) = delete;

    PackedPtr& operator=(const PackedPtr&) = delete;

    //----- --- -- -  -  -   -

    void reset() noexcept
    {
        this->offset_ = 0;
    }

    void clear() noexcept
    {
        this->reset();
    }

    void reset(const T* target) noexcept
    {
        this->offset_ = byte_distance(this, target);
        BATT_CHECK_EQ((const void*)target, (const void*)this->get());
    }

    const T* get() const noexcept
    {
        return reinterpret_cast<const T*>(advance_pointer(this, this->offset_.value()));
    }

    T* get_mut() noexcept
    {
        return reinterpret_cast<T*>(advance_pointer(this, this->offset_.value()));
    }

    const T* operator->() const noexcept
    {
        return this->get();
    }

    T* operator->() noexcept
    {
        return this->get();
    }

    const_reference operator*() const noexcept
#if BATT_CPP_20
        requires(!std::is_same_v<std::decay_t<T>, void>)
#endif
    {
        return *this->get();
    }

    reference operator*() noexcept
#if BATT_CPP_20
        requires(!std::is_same_v<std::decay_t<T>, void>)
#endif
    {
        return *this->get();
    }

    const_reference operator[](isize index) const noexcept
#if BATT_CPP_20
        requires(!std::is_same_v<std::decay_t<T>, void>)
#endif
    {
        return *(this->get() + index);
    }

    reference operator[](isize index) noexcept
#if BATT_CPP_20
        requires(!std::is_same_v<std::decay_t<T>, void>)
#endif
    {
        return *(this->get_mut() + index);
    }

    explicit operator bool() const noexcept
    {
        return this->offset_ != 0;
    }

    void advance(isize delta) noexcept
    {
        if (delta < 0) {
            this->offset_ -= sizeof(T) * -delta;
        } else {
            this->offset_ += sizeof(T) * delta;
        }
    }
};

#if BATT_CPP_20

template <typename LeftT, typename LeftOffsetT, typename RightT, typename RightOffsetT>
inline auto operator<=>(const PackedPtr<LeftT, LeftOffsetT>& left,
                        const PackedPtr<RightT, RightOffsetT>& right) noexcept
{
    return static_cast<const void*>(left.get()) <=> static_cast<const void*>(right.get());
}

#endif  // BATT_CPP_20

template <typename T, typename OffsetT>
inline bool operator==(const PackedPtr<T, OffsetT>& ptr, std::nullptr_t) noexcept
{
    return ptr.offset_ == 0;
}

template <typename T, typename OffsetT>
inline bool operator==(std::nullptr_t, const PackedPtr<T, OffsetT>& ptr) noexcept
{
    return ptr.offset_ == 0;
}

template <typename T, typename OffsetT>
inline bool operator!=(const PackedPtr<T, OffsetT>& ptr, std::nullptr_t) noexcept
{
    return ptr.offset_ != 0;
}

template <typename T, typename OffsetT>
inline bool operator!=(std::nullptr_t, const PackedPtr<T, OffsetT>& ptr) noexcept
{
    return ptr.offset_ != 0;
}

}  //namespace batt
